  | _, _ => farm1_0_1RB1RA_0LC0RC_0LD0RB_1LA1LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RA_0LC0RC_0LD0RB_1LA1LD (r ph : nat) : nat :=
