          (mkC StD (mkS [S0;S0] [] 0 0 []) S0 (mkS [S0;S1] [S0] 1 0 [S1])) 0 10.
Definition ch_arm12_1RB1RA_1LC1LB_0RD0LC_1LB0RA : list rstep := [RB (SWinL 10)].
