  check_arm tm true true rules arm12_1RB1RA_1LC1LB_0RD0LC_1LB0RA ch_arm12_1RB1RA_1LC1LB_0RD0LC_1LB0RA = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm12_1RB1RA_1LC1LB_0RD0LC_1LB0RA : RuleSound tm true true arm12_1RB1RA_1LC1LB_0RD0LC_1LB0RA.
