(** ** What this board establishes

    8 of 12 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 12 of them
    collapse to 3 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    2 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB1RA_1LC1LB_0RD0LC_1LB0RA : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [S1] [S1] 2 0 [S0;S0]) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StA (mkS [S1] [S1] 2 2 [S0;S0]) S0 (mkS [] [] 0 0 [])) 4 10, [RB (SWin 3);RB (SCycL 1 0);RB (SWin 4);RB (SCycR 1);RB (SWin 3);RB (SFoldL 2)]);
   (mkLRule (mkC StD (mkS [S0] [] 0 0 []) S1 (mkS [S1] [S1] 2 0 [S0;S1])) (mkC StD (mkS [S0] [] 0 0 []) S1 (mkS [S1] [S1] 2 2 [])) 4 8, [RB (SWin 1);RB (SCycR 1);RB (SWin 4);RB (SCycL 1 0);RB (SWin 3);RB (SRotR 1);RB (SRotR 1);RB (SFoldR 2)])].
Definition nrules_1RB1RA_1LC1LB_0RD0LC_1LB0RA : list LRule := map fst nlad_1RB1RA_1LC1LB_0RD0LC_1LB0RA.
Local Notation nrules := nrules_1RB1RA_1LC1LB_0RD0LC_1LB0RA.

Lemma nladder_ok_1RB1RA_1LC1LB_0RD0LC_1LB0RA : check_ladder tm [] nlad_1RB1RA_1LC1LB_0RD0LC_1LB0RA = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1RA_1LC1LB_0RD0LC_1LB0RA : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1RA_1LC1LB_0RD0LC_1LB0RA. Qed.

Definition iarm0_0_1RB1RA_1LC1LB_0RD0LC_1LB0RA : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_1RB1RA_1LC1LB_0RD0LC_1LB0RA : list nseg :=
  [NCh [RB (SWinL 10)]].
Lemma ok_iarm0_0_1RB1RA_1LC1LB_0RD0LC_1LB0RA :
  check_narm tm true false nrules iarm0_0_1RB1RA_1LC1LB_0RD0LC_1LB0RA ch_iarm0_0_1RB1RA_1LC1LB_0RD0LC_1LB0RA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB1RA_1LC1LB_0RD0LC_1LB0RA : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 [S0;S0]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [S0;S0] 1 0 [S0;S1])) 0 1.
Definition ch_iarm0_1_1RB1RA_1LC1LB_0RD0LC_1LB0RA : list nseg :=
  [NCh [RB (SWinL 5);RB (SRotR 1)];
   NUp 0 [] [S1;S0] 0 1 0 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) true;
   NCh [RB (SWin 3);RB (SCycL 1 0);RB (SWin 2)]].
Lemma ok_iarm0_1_1RB1RA_1LC1LB_0RD0LC_1LB0RA :
  check_narm tm true false nrules iarm0_1_1RB1RA_1LC1LB_0RD0LC_1LB0RA ch_iarm0_1_1RB1RA_1LC1LB_0RD0LC_1LB0RA = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_0_1RB1RA_1LC1LB_0RD0LC_1LB0RA : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 [S1]))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [S0;S0] 1 0 [S0;S0;S1])) 0 1.
Definition ch_farm1_0_1RB1RA_1LC1LB_0RD0LC_1LB0RA : list nseg :=
