   NUp 1 [] [S0;S1] 0 1 0 (mkS [] [] 0 0 []) (mkS [S1] [] 0 0 []) true;
   NCh [RB (SWin 1);RB (SCycR 1);RB (SWin 1);RB (SWinR 5);RB (SCycL 1 0);RB (SWin 2)]].
