   (mkLRule (mkC StC (mkS [S1;S1] [S1] 2 2 [S0]) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [S1] 2 2 [S0]) S1 (mkS [S0;S0] [] 0 0 [])) 0 2, [RB (SWin 2)]);
   (mkLRule (mkC StD (mkS [S0] [] 0 0 []) S0 (mkS [S1;S1] [S1] 2 0 [S0;S1])) (mkC StD (mkS [S0] [] 0 0 []) S0 (mkS [S1;S1] [S1] 2 2 [])) 4 12, [RB (SWin 2);RB (SCycR 1);RB (SWin 4);RB (SCycL 1 0);RB (SWin 6);RB (SRotR 1);RB (SRotR 1);RB (SFoldR 2)]);
   (mkLRule (mkC StC (mkS [S1;S1] [S1] 2 2 [S0]) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [S1] 2 2 [S0]) S1 (mkS [S0;S0] [] 0 0 [])) 0 2, [RB (SWin 2)])].
Definition nrules_1RB1RA_1LC1LB_0RD0LD_0RA0LC : list LRule := map fst nlad_1RB1RA_1LC1LB_0RD0LD_0RA0LC.
