  | _, _ => farm1_0_1RB1RA_1LC1LB_0RD0LD_0RA0LC  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RA_1LC1LB_0RD0LD_0RA0LC (r ph : nat) : nat :=
