(** ** What this board establishes

    9 of 11 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 11 of them
    collapse to 4 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 2
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    2 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB1RA_1LC1LD_0RA0LC_0RA1LD : list (LRule * list rstep) :=
  [(mkLRule (mkC StA (mkS [] [S1] 2 0 [S0]) S0 (mkS [S1;S0] [] 0 0 [])) (mkC StA (mkS [] [S1] 2 2 [S0]) S0 (mkS [] [] 0 0 [])) 4 6, [RB (SWin 2);RB (SCycL 1 0);RB (SWin 2);RB (SCycR 1);RB (SWin 2);RB (SFoldL 2)]);
   (mkLRule (mkC StB (mkS [S1] [S1] 2 0 [S0]) S1 (mkS [S0;S1] [] 0 0 [])) (mkC StB (mkS [S1] [S1] 2 2 [S0]) S1 (mkS [] [] 0 0 [])) 4 6, [RB (SWin 1);RB (SCycL 1 0);RB (SWin 2);RB (SCycR 1);RB (SWin 3);RB (SFoldL 2)])].
Definition nrules_1RB1RA_1LC1LD_0RA0LC_0RA1LD : list LRule := map fst nlad_1RB1RA_1LC1LD_0RA0LC_0RA1LD.
Local Notation nrules := nrules_1RB1RA_1LC1LD_0RA0LC_0RA1LD.

Lemma nladder_ok_1RB1RA_1LC1LD_0RA0LC_0RA1LD : check_ladder tm [] nlad_1RB1RA_1LC1LD_0RA0LC_0RA1LD = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1RA_1LC1LD_0RA0LC_0RA1LD : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1RA_1LC1LD_0RA0LC_0RA1LD. Qed.

Definition iarm0_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [] 0 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD : list nseg :=
  [NCh [RB (SWin 4)]].
Lemma ok_iarm0_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD :
  check_narm tm true false nrules iarm0_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD ch_iarm0_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB1RA_1LC1LD_0RA0LC_0RA1LD : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [S0;S1] 1 0 [S0;S0]))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [S0;S0] 1 0 [S0;S1])) 0 1.
Definition ch_iarm0_1_1RB1RA_1LC1LD_0RA0LC_0RA1LD : list nseg :=
  [NCh [RB (SWin 1);RB (SRotR 1)];
   NUp 0 [] [S1;S0] 0 1 0 (mkS [] [] 0 0 []) (mkS [S0] [] 0 0 []) true;
   NCh [RB (SWin 2);RB (SCycL 1 0);RB (SWin 1)]].
Lemma ok_iarm0_1_1RB1RA_1LC1LD_0RA0LC_0RA1LD :
  check_narm tm true false nrules iarm0_1_1RB1RA_1LC1LD_0RA0LC_0RA1LD ch_iarm0_1_1RB1RA_1LC1LD_0RA0LC_0RA1LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S0;S0;S1] [] 0 0 [])) 0 1.
Definition ch_farm1_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD : list nseg :=
  [NCh [RB (SWin 6);RB (SWinR 6)]].
Lemma ok_farm1_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD :
  check_narm tm true true nrules farm1_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD ch_farm1_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm2_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD : LRule :=
  mkLRule (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S1;S0;S1] [S0;S1] 1 0 []))
          (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [S0;S0] 1 0 [S0;S0;S0;S1])) 0 1.
Definition ch_farm2_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD : list nseg :=
  [NCh [RB (SWin 2)];
   NUp 1 [] [S0;S1] 0 1 0 (mkS [] [] 0 0 []) (mkS [] [] 0 0 []) true;
   NCh [RB (SWin 1);RB (SCycL 1 0);RB (SWin 2);RB (SCycR 1);RB (SWin 1);RB (SWinR 5);RB (SCycL 1 0);RB (SWin 1)]].
Lemma ok_farm2_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD :
  check_narm tm true true nrules farm2_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD ch_farm2_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1RA_1LC1LD_0RA0LC_0RA1LD (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD
  | 0, 1 => iarm0_1_1RB1RA_1LC1LD_0RA0LC_0RA1LD
  | _, _ => iarm0_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

(** The fill arms, one per arm index and PHASE.  Both tails are known
    empty -- they are the only arms that see the end of the counter -- and
    the arm at index [r] has [r] guaranteed block copies materialised into
    [s_pre], without which it has no chain at all.  [fm1]/[fm2] say how the
    fill target's own guaranteed copies divide about the block.

    The phase is the second index because the fill arm is the ONLY one that
    sees a terminator: it leaves from the terminator of its own phase and
    lands on the terminator of the phase its law names.  The interior arms
    keep the terminator in the opaque tail and are phase-free. *)
Definition farm_1RB1RA_1LC1LD_0RA0LC_0RA1LD (r ph : nat) : LRule :=
  match r, ph with
  | 1, 0 => farm1_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD
  | 2, 0 => farm2_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD
  | _, _ => farm1_0_1RB1RA_1LC1LD_0RA0LC_0RA1LD  (* unreachable: 0 < r < N0 + st *)
  end.

Definition fm1_1RB1RA_1LC1LD_0RA0LC_0RA1LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 1 | 2, 0 => 1 | _, _ => 0 end.
Definition fm2_1RB1RA_1LC1LD_0RA0LC_0RA1LD (r ph : nat) : nat :=
  match r, ph with | 1, 0 => 0 | 2, 0 => 1 | _, _ => 0 end.

(** One chain per UNPINNED INSTRUCTION per fill arm, at the VISIT PHASE
    0.  [fire_of_run_instr] turns each into a fire of that instruction,
    and [tops_cofinal_at] says the tops of that phase keep coming.  The fill
    arm is the counter's overflow, so this is where the rare instruction of
    a sparse row is witnessed. *)
Definition vis_1RB1RA_1LC1LD_0RA0LC_0RA1LD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S0) => [SWin 1]
  | 1, (StA, S1) => [SWin 5]
  | 1, (StB, S0) => [SWinR 8]
  | 1, (StB, S1) => [SWin 2]
  | 1, (StC, S0) => []
  | 1, (StC, S1) => [SWinR 9]
  | 1, (StD, S0) => [SWin 4]
  | 1, (StD, S1) => [SWin 3]
  | 2, (StA, S0) => [SWin 1]
  | 2, (StA, S1) => [SWin 5]
  | 2, (StB, S0) => [SWin 1;SCycL 1 0;SWin 2;SCycR 1;SWinR 3]
  | 2, (StB, S1) => [SWin 2]
  | 2, (StC, S0) => [SWin 0]
  | 2, (StC, S1) => [SWin 1;SCycL 1 0;SWin 2;SCycR 1;SWinR 4]
  | 2, (StD, S0) => [SWin 4]
  | 2, (StD, S1) => [SWin 3]
  | _, _ => []
  end.

(** ...each after its segment program: a visit that fires past the rounds
    of a nested fill arm first runs that arm's program up to them. *)
