  mkLRule (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [] 0 0 []))
          (mkC StB (mkS [] [] 0 0 []) S0 (mkS [S0;S1] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_1RB1RA_1LC1LD_0RB0LC_0RA1LB : list nseg :=
  [NCh [RB (SWinL 10)]].
