  mkLRule (mkC StB (mkS [S0;S0] [S0] 1 0 [S1]) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S1;S0] [S0] 1 0 [S1]) S0 (mkS [] [] 0 0 [])) 0 2.
Definition ch_arm12_1RB1RC_0LA0RC_0LD0RB_1LD1LA : list rstep := [RB (SWin 2)].
Lemma ok_arm12_1RB1RC_0LA0RC_0LD0RB_1LD1LA :
  check_arm tm true true rules arm12_1RB1RC_0LA0RC_0LD0RB_1LD1LA ch_arm12_1RB1RC_0LA0RC_0LD0RB_1LD1LA = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm12_1RB1RC_0LA0RC_0LD0RB_1LD1LA : RuleSound tm true true arm12_1RB1RC_0LA0RC_0LD0RB_1LD1LA.
Proof. eapply arm_sound; [exact rules_sound_1RB1RC_0LA0RC_0LD0RB_1LD1LA | exact ok_arm12_1RB1RC_0LA0RC_0LD0RB_1LD1LA]. Qed.

