(** ** What this board establishes

    10 of 12 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 12 of them
    collapse to 4 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 2
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    2 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB1RD_0LC0RB_1LA1LC_0LC1RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StC (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [S1] 2 0 [S0])) (mkC StC (mkS [] [] 0 0 []) S0 (mkS [] [S1] 2 2 [S0])) 4 6, [RB (SWin 2);RB (SCycR 1);RB (SWin 2);RB (SCycL 1 0);RB (SWin 2);RB (SFoldR 2)]);
   (mkLRule (mkC StA (mkS [S0;S1] [] 0 0 []) S1 (mkS [S1] [S1] 2 0 [S0])) (mkC StA (mkS [] [] 0 0 []) S1 (mkS [S1] [S1] 2 2 [S0])) 4 6, [RB (SWin 1);RB (SCycR 1);RB (SWin 2);RB (SCycL 1 0);RB (SWin 3);RB (SFoldR 2)])].
Definition nrules_1RB1RD_0LC0RB_1LA1LC_0LC1RD : list LRule := map fst nlad_1RB1RD_0LC0RB_1LA1LC_0LC1RD.
Local Notation nrules := nrules_1RB1RD_0LC0RB_1LA1LC_0LC1RD.

Lemma nladder_ok_1RB1RD_0LC0RB_1LA1LC_0LC1RD : check_ladder tm [] nlad_1RB1RD_0LC0RB_1LA1LC_0LC1RD = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1RD_0LC0RB_1LA1LC_0LC1RD : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1RD_0LC0RB_1LA1LC_0LC1RD. Qed.

Definition iarm0_0_1RB1RD_0LC0RB_1LA1LC_0LC1RD : LRule :=
  mkLRule (mkC StB (mkS [S0;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S0;S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 1.
