    destruct r as [|r].
    { eapply narm_reach; [exact nrules_sound_1RB1RD_0LC0RB_1LA1LC_0LC1RD | exact ok_iarm0_1_1RB1RD_0LC0RB_1LA1LC_0LC1RD]. }
    exfalso; lia.
